			session:         &Session{DispatcherMode: 0},
			group:           &Group{DispatcherMode: 1},
			expectedEnabled: false,
		},
		{
			name:            "session uses group default when set to -1 and group enabled",
			session:         &Session{DispatcherMode: -1},
			group:           &Group{DispatcherMode: 1},
			expectedEnabled: true,
		},
		{
			name:            "session uses group default when set to -1 and group disabled",
			session:         &Session{DispatcherMode: -1},
			group:           &Group{DispatcherMode: 0},
			expectedEnabled: false,
		},
		{
			name:            "no session, group enabled",
			session:         nil,
			group:           &Group{DispatcherMode: 1},
			expectedEnabled: true,
		},
		{
			name:            "no session, group disabled",
			session:         nil,
			group:           &Group{DispatcherMode: 0},
			expectedEnabled: false,
		},
