// ── prependConversationHistory ───────────────────────────────────────────────────

func TestPrependConversationHistory(t *testing.T) {
	tests := []struct {
		name           string
		history        []*ConversationMessage
		prompt         string
		expectedPrefix string
		checkInOutput  string
	}{
		{
			name:           "empty history returns prompt unchanged",
			history:        []*ConversationMessage{},
			prompt:         "Hello, how can I help?",
			expectedPrefix: "",
			checkInOutput:  "Hello, how can I help?",
		},
		{
			name: "single user message",
			history: []*ConversationMessage{
				{Role: "user", Content: "What's the weather?"},
			},
			prompt:         "Hello, how can I help?",
			expectedPrefix: "[Conversation history — prior exchanges in this topic]\n\n",
			checkInOutput:  "User: What's the weather?",
		},
		{
			name: "user and assistant exchange",
			history: []*ConversationMessage{
				{Role: "user", Content: "What's the weather?"},
				{Role: "assistant", Content: "The weather is sunny."},
			},
			prompt:         "Continue from there",
			expectedPrefix: "[Conversation history — prior exchanges in this topic]\n\n",
			checkInOutput:  "User: What's the weather?",
		},
		{
			name: "long content is truncated",
			history: []*ConversationMessage{
				{Role: "user", Content: string(make([]byte, 1000))}, // 1000 bytes
			},
			prompt:         "Hello",
			expectedPrefix: "[Conversation history — prior exchanges in this topic]\n\n",
			checkInOutput:  "…", // truncation marker
		},
		{
			name: "multiple exchanges",
			history: []*ConversationMessage{
				{Role: "user", Content: "First question"},
				{Role: "assistant", Content: "First answer"},
				{Role: "user", Content: "Second question"},
				{Role: "assistant", Content: "Second answer"},
			},
			prompt:         "Third question",
			expectedPrefix: "[Conversation history — prior exchanges in this topic]\n\n",
			checkInOutput:  "User: First question",
		},
		{
			name: "prompt appears after separator",
			history: []*ConversationMessage{
				{Role: "user", Content: "Previous message"},
			},
			prompt:         "New prompt",
			expectedPrefix: "[Conversation history — prior exchanges in this topic]\n\n",
			checkInOutput:  "\n---\n\nNew prompt",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := prependConversationHistory(tc.history, tc.prompt)

			// Check for expected prefix
			if tc.expectedPrefix != "" && !startsWith(got, tc.expectedPrefix) {
				t.Errorf("prependConversationHistory() output should start with %q, got: %q", tc.expectedPrefix, got)
			}

			// Check for content in output
			if tc.checkInOutput != "" && !contains(got, tc.checkInOutput) {
				t.Errorf("prependConversationHistory() output should contain %q, got: %q", tc.checkInOutput, got)
			}

			// For empty history, verify prompt is unchanged
			if len(tc.history) == 0 && got != tc.prompt {
				t.Errorf("prependConversationHistory() with empty history = %q, want %q", got, tc.prompt)
			}
		})
	}
}

func TestPrependConversationHistory_Truncation(t *testing.T) {
	// Test that messages longer than maxContentLen are truncated
	longContent := string(make([]byte, 900)) // 900 bytes, over the 800 limit
	history := []*ConversationMessage{
		{Role: "user", Content: longContent},
	}

	result := prependConversationHistory(history, "Next message")

	// Should contain truncation marker
	if !contains(result, "…") {
		t.Error("Long content should be truncated with '…'")
	}

	// Should not contain the full original content
	if contains(result, longContent) {
		t.Error("Result should not contain full long content")
	}
}

