func TestApplyTierChange_EdgeCases(t *testing.T) {
	tests := []struct {
		name          string
		currentModel  string
		delta         int
		expectedModel string
		expectedChanged bool
	}{
		{
			name:          "escalate from haiku to sonnet",
			currentModel:  "claude-haiku-4-5",
			delta:         1,
			expectedModel: "claude-sonnet-4-6",
			expectedChanged: true,
		},
		{
			name:          "escalate from sonnet to opus",
			currentModel:  "claude-sonnet-4-6",
			delta:         1,
			expectedModel: "claude-opus-4-6",
			expectedChanged: true,
		},
		{
			name:          "de-escalate from opus to sonnet",
			currentModel:  "claude-opus-4-6",
			delta:         -1,
			expectedModel: "claude-sonnet-4-6",
			expectedChanged: true,
		},
		{
			name:          "de-escalate from sonnet to haiku",
			currentModel:  "claude-sonnet-4-6",
			delta:         -1,
			expectedModel: "claude-haiku-4-5",
			expectedChanged: true,
		},
		{
			name:          "already at top - opus",
			currentModel:  "claude-opus-4-6",
			delta:         1,
			expectedModel: "claude-opus-4-6",
			expectedChanged: false,
		},
		{
			name:          "already at bottom - haiku",
			currentModel:  "claude-haiku-4-5",
			delta:         -1,
			expectedModel: "claude-haiku-4-5",
			expectedChanged: false,
		},
		{
			name:          "unknown model defaults to sonnet, then escalate",
			currentModel:  "unknown-model",
			delta:         1,
			expectedModel: "claude-opus-4-6",
			expectedChanged: true,
		},
		{
			name:          "double escalation from haiku to opus",
			currentModel:  "claude-haiku-4-5",
			delta:         2,
			expectedModel: "claude-opus-4-6",
			expectedChanged: true,
		},
		{
			name:          "double de-escalation from opus to haiku",
			currentModel:  "claude-opus-4-6",
			delta:         -2,
			expectedModel: "claude-haiku-4-5",
			expectedChanged: true,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			model, changed, _ := applyTierChange(tc.currentModel, tc.delta)
			if model != tc.expectedModel {
				t.Errorf("model = %q, want %q", model, tc.expectedModel)
			}
			if changed != tc.expectedChanged {
				t.Errorf("changed = %v, want %v", changed, tc.expectedChanged)
			}
		})
	}
}

